jobs.package-qualification:
name: Package qualification
needs: [changes, qualification, native-host-package, mac-runner]
if: ${{ always() }}
outputs:
  qualified_revision: ${{ steps.qualified.outputs.revision }}
runs-on: ubuntu-24.04
steps:
  - name: Require a complete classification decision
    env:
      RESULT: ${{ needs.changes.result }}
      CODE: ${{ needs.changes.outputs.code }}
      PORTABLE_REQUIRED: ${{ needs.changes.outputs.portable }}
      MACOS: ${{ needs.changes.outputs.package_macos }}
      LINUX: ${{ needs.changes.outputs.package_linux }}
      FIXTURES: ${{ needs.changes.outputs.fixtures }}
      NATIVE_REQUIRED: ${{ needs.changes.outputs.native }}
      PLATFORM: ${{ needs.changes.outputs.native_platform }}
      READY: ${{ needs.changes.outputs.ready }}
      MAC_RUNNER_RESULT: ${{ needs.mac-runner.result }}
    run: |
      test "$RESULT" = success
      test "$MAC_RUNNER_RESULT" = success
      for flag in "$CODE" "$PORTABLE_REQUIRED" "$MACOS" "$LINUX" "$FIXTURES" "$NATIVE_REQUIRED" "$READY"; do
        case "$flag" in true|false) ;; *) exit 1 ;; esac
      done
      expected_native=false; expected_platform=all
      macos=false; linux=false
      if [ "$MACOS" = true ] || [ "$FIXTURES" = true ]; then macos=true; fi
      if [ "$LINUX" = true ] || [ "$FIXTURES" = true ]; then linux=true; fi
      if [ "$macos" = true ] || [ "$linux" = true ]; then expected_native=true; fi
      if [ "$macos" != "$linux" ]; then
        if [ "$macos" = true ]; then expected_platform=macos; else expected_platform=linux_x86_64; fi
      fi
      test "$NATIVE_REQUIRED" = "$expected_native"
      if [ "$NATIVE_REQUIRED" = true ]; then test "$PORTABLE_REQUIRED" = true; fi
      test "$PLATFORM" = "$expected_platform"
      if [ "$CODE" = false ]; then
        test "$PORTABLE_REQUIRED/$MACOS/$LINUX/$FIXTURES" = false/false/false/false
      fi
      if [ "$NATIVE_REQUIRED" = true ] && [ "$READY" = false ]; then
        echo 'Draft PR: affected native qualification deferred; this required context remains non-passing until ready qualification succeeds.' >> "$GITHUB_STEP_SUMMARY"
        exit 1
      fi
  - name: Require every requested native and package-input qualification
    env:
      PORTABLE: ${{ needs.qualification.result }}
      NATIVE_REQUIRED: ${{ needs.changes.outputs.native }}
      PACKAGE: ${{ needs.native-host-package.result }}
      MACOS: ${{ needs.changes.outputs.package_macos }}
      LINUX: ${{ needs.changes.outputs.package_linux }}
      FIXTURES: ${{ needs.changes.outputs.fixtures }}
    run: |
      test "$PORTABLE" = success
      case "$NATIVE_REQUIRED" in
        false)
          test "$PACKAGE" = skipped
          echo 'No native inputs changed; behavioral checks intentionally omitted, not executed.' >> "$GITHUB_STEP_SUMMARY" ;;
        true)
          test "$PACKAGE" = success
          echo "Native qualification passed at $GITHUB_SHA. Selected helpers: macOS=$MACOS, Linux=$LINUX; selected process/updater fixtures=$FIXTURES. Unselected consumers intentionally omitted, not executed." >> "$GITHUB_STEP_SUMMARY" ;;
        *) exit 1 ;;
      esac
  - name: Bind complete successful qualification to the exact source
    id: qualified
    if: github.event_name != 'pull_request' && (github.event_name != 'push' || startsWith(github.ref, 'refs/tags/')) && needs.changes.outputs.portable == 'true' && needs.changes.outputs.package_macos == 'true' && needs.changes.outputs.package_linux == 'true' && needs.changes.outputs.fixtures == 'true'

    run: echo "revision=$GITHUB_SHA" >> "$GITHUB_OUTPUT"

  - name: Verify the exact-source qualification receipt
    env:
      RESULT: ${{ needs.changes.result }}
      PORTABLE_REQUIRED: ${{ needs.changes.outputs.portable }}
      MACOS: ${{ needs.changes.outputs.package_macos }}
      LINUX: ${{ needs.changes.outputs.package_linux }}
      FIXTURES: ${{ needs.changes.outputs.fixtures }}
      QUALIFIED_REVISION: ${{ steps.qualified.outputs.revision }}
      ORDINARY: ${{ github.event_name == 'pull_request' || (github.event_name == 'push' && !startsWith(github.ref, 'refs/tags/')) }}
    run: |
      test "$RESULT" = success
      for flag in "$PORTABLE_REQUIRED" "$MACOS" "$LINUX" "$FIXTURES"; do
        case "$flag" in true|false) ;; *) exit 1 ;; esac
      done
      case "${ORDINARY:-false}" in true|false) ;; *) exit 1 ;; esac
      if [ "${ORDINARY:-false}" != true ] && [ "$PORTABLE_REQUIRED/$MACOS/$LINUX/$FIXTURES" = true/true/true/true ]; then
        test "$QUALIFIED_REVISION" = "$GITHUB_SHA"
      else
        test -z "$QUALIFIED_REVISION"
      fi
      echo "Selected current-source checks passed: helper/package macOS=$MACOS, Linux=$LINUX; process/updater fixtures=$FIXTURES. Unselected checks intentionally omitted, not executed. This is fixture proof; selected-environment image qualification and installed composition are separate explicit integration." >> "$GITHUB_STEP_SUMMARY"
